import re
from .epc_section_generic import EpcSectionGeneric, EpcLine
from ..utils.logger import logger


class SectionPgw(EpcSectionGeneric):
    """
    Section "Pgw" is a part of epc.lua config file.
    Generated content base on epc.yaml.
    Example generated for CLOUD_R4A_CUS:

    exec("set_pgw id=1 ip=:10000 apn=nokia1.net devtype=tun devname=tunPGW_1 addr=30.61.255.254/16")
    exec("set_pgw id=2 ip=:10000 apn=nokia2.net devtype=tun devname=tunPGW_2 addr=30.62.255.254/16")
    """

    def _prepare_section_content(self, epc_config, *args, **kwargs):
        pgw_keys = filter(self._filter_pgw, sorted(epc_config.keys()))
        if not pgw_keys:
            return

        logger.debug("Generating PGW section")
        subsection = []
        for pgw in pgw_keys:
            pgw_data = epc_config[pgw]
            pgw_num = re.match(r'pgw(?P<pgw_num>\d+)', pgw).group('pgw_num')
            apn = pgw_data['apn'] if 'apn' in pgw_data else 'nsn.com'
            addr = f"{pgw_data['pgw_addr']}/{pgw_data['pgw_addr_mask']}"

            pgw_line = f"set_pgw id={pgw_num} ip=:{self.EDAEMON_PORT} apn={apn} " \
                       f"devtype=tun devname=tunPGW_{pgw_num} addr={addr}"
            subsection.append(EpcLine(line=pgw_line, exec=True, tab_count=0))

        self._section_content.append(subsection)

    @staticmethod
    def _filter_pgw(s):
        return re.match(r'pgw\d+', s) is not None
